use std::io::{self, BufRead};
use world_feed::{live::command_payload, Command};
fn main() {
    for line in io::stdin().lock().lines() {
        let line=line.unwrap();
        let v: Vec<u32>=line.split_whitespace().map(|s| s.parse().unwrap()).collect();
        let c=Command::RegenerateRoster{seed:17, friend_groups:v[0], solos:v[1], friends_per_group_min:v[2], friends_per_group_max:v[3]};
        match command_payload(&c) { Ok(p)=>println!("OK\t{}",p), Err(_)=>println!("ERR") }
    }
}
